func:
// 1. Читаем текущее значение счетчика из flow-контекста (если его нет, берем 0)
let count = flow.get("msgCount") || 0;

// 2. Увеличиваем счетчик на 1
count += 1;

// 3. Сохраняем новое значение обратно в flow-контекст
flow.set("msgCount", count);

// 4. Получаем время последнего вызова
let lastTime = flow.get("lastAccessTime") || "First run";
let currentTime = new Date().toISOString();

// 5. Сохраняем текущее время как последнее
flow.set("lastAccessTime", currentTime);

// 6. Формируем красивый ответ для отладки
msg.payload = {
    student: "Piltitskaya",
    lab: "2.12",
    messageCounter: count,
    previousAccessTime: lastTime,
    currentAccessTime: currentTime
};

return msg;
